PREFIXES = ('Interest payout: ', 'ब्याज भुगतान: ', 'व्याज payout: ')       # (the schedule's description, in each language)


def link_existing_payout_schedules(apps, schema_editor):
    """Payout schedules made by the FD setup before this link existed: tie each to the deposit it was named after."""
    Account = apps.get_model('expenses', 'Account')
    RecurringTransaction = apps.get_model('expenses', 'RecurringTransaction')
    schedules = RecurringTransaction.objects.filter(
        transaction_type='INCOME', source='Interest Income', payout_for__isnull=True)
    for schedule in schedules:
        name = next((schedule.description[len(p):] for p in PREFIXES if schedule.description.startswith(p)), None)
        if not name:
            continue
        deposits = Account.objects.filter(user_id=schedule.user_id, name=name, deposit_payout__isnull=False)
        if deposits.count() == 1:
            schedule.payout_for = deposits.get()
            schedule.save(update_fields=['payout_for'])


